+	await act(async () => {
+		alerts.buttons[0]?.[1]?.onPress?.();
+		await Promise.resolve();
+	});
+
+	expect(first.requests).toEqual(["evener/upgrade", "evener/settings/overview"]);
+	expect(first.checkpoint()?.response).toEqual(response);
+});
