+export function useRenderClient(
+	client: AppwireClient | null,
+	state: ConnectionState,
+	hubId: string,
+): AppwireClient | null {
+	const lastClient = useRef<AppwireClient | null>(null);
+	const scope = useRef(hubId);
+	if (scope.current !== hubId) {
+		scope.current = hubId;
+		lastClient.current = null;
+	}
